import React from 'react';
import { Layout, Grid } from 'antd';
import { usePlatform } from '../hooks/usePermissions';
import { useTheme } from '../hooks/useTheme';
import PermissionBasedMenu from './PermissionBasedMenu';
import ModernHeader from './ModernHeader';
import ThemeToggle from './ThemeToggle';
import BuildBadge from './BuildBadge';
import DiagPanel from './DiagPanel';

const { Header, Content, Sider } = Layout;

// Убираем antd Layout для MiniApp (устойчивый простой layout)

interface PlatformLayoutProps {
  children: React.ReactNode;
  activePersonality?: string;
  headerOnly?: boolean;
}

const PlatformLayout: React.FC<PlatformLayoutProps> = ({ 
  children, 
  activePersonality,
  headerOnly = false,
}) => {
  const { platform, isMiniApp, isWeb } = usePlatform();
  const { isDark, isLight } = useTheme();

  // Стили для мини-апп
  const getMiniAppStyles = () => ({
    height: '100dvh',
    overflow: 'hidden',
    background: 'var(--sp-gradient-background)',
    boxSizing: 'border-box' as const,
  });

  // Стили для веб-версии
  const getWebStyles = () => ({
    minHeight: '100vh',
    background: 'var(--sp-gradient-background)',
  });

  // Рендеринг для мини-апп (устойчивый Layout из рабочей версии)
  if (isMiniApp) {
    return (
      <Layout style={getMiniAppStyles()} className="sp-platform-container sp-platform-telegram telegram-mini-app">
        <div className="sp-greeting" style={{padding:'4px 8px', fontWeight:600}}>Привет!</div>
        <Header 
          className="sp-header"
          style={{ 
            padding: '0 var(--sp-spacing-md)', 
            height: 'var(--sp-platform-header-height)',
            background: 'var(--sp-bg-card)',
            backdropFilter: 'blur(10px)',
            borderBottom: '1px solid var(--sp-border-primary)',
            display: 'flex', alignItems: 'center', justifyContent: 'space-between'
          }}
        >
          <SectionBoundary label="ModernHeader"><ModernHeader activePersonality={activePersonality} /></SectionBoundary>
          <SectionBoundary label="ThemeToggle"><ThemeToggle variant="icon" size="small" /></SectionBoundary>
        </Header>

        <Content 
          className="sp-content"
          style={{ 
            padding: 'var(--sp-spacing-sm)',
            overflowX: 'hidden',
            overflowY: 'auto',
            height: headerOnly ? 'calc(100vh - var(--sp-platform-header-height))' : 'calc(100vh - var(--sp-platform-header-height) - 60px)'
          }}
        >
          {children}
        </Content>

        {!headerOnly && (
          <div 
            className="sp-bottom-menu"
            style={{
              height: '60px',
              background: 'var(--sp-bg-card)',
              backdropFilter: 'blur(10px)',
              borderTop: '1px solid var(--sp-border-primary)',
              display: 'flex', alignItems: 'center', padding: '0 var(--sp-spacing-sm)',
              overflow: 'hidden'
            }}
          >
            <PermissionBasedMenu />
            <div style={{marginLeft:'auto', paddingLeft:8}}><BuildBadge /></div>
          </div>
        )}
        <DiagPanel />
      </Layout>
    );
  }

  const [collapsed, setCollapsed] = React.useState(false);

  // Рендеринг для веб-версии (как в рабочей архивной версии)
  return (
    <Layout style={getWebStyles()} className="sp-platform-container sp-platform-web">
      <div className="sp-greeting" style={{padding:'4px 8px', fontWeight:600}}>Привет!</div>
      <Header 
        className="sp-header"
        style={{ 
          padding: '0 var(--sp-spacing-lg)', 
          height: 'var(--sp-platform-header-height)',
          background: 'var(--sp-bg-card)',
          backdropFilter: 'blur(10px)',
          borderBottom: '1px solid var(--sp-border-primary)',
          position: 'sticky',
          top: 0,
          zIndex: 2000,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <SectionBoundary label="ModernHeader"><ModernHeader activePersonality={activePersonality} /></SectionBoundary>
        <SectionBoundary label="ThemeToggle"><ThemeToggle variant="dropdown" showText={true} /></SectionBoundary>
      </Header>

      {headerOnly ? (
        <Content 
          className="sp-content"
          style={{ 
            padding: 'var(--sp-spacing-lg)',
            minHeight: 'calc(100vh - var(--sp-platform-header-height))',
            overflow: 'auto',
          }}
        >
          {children}
          <div style={{display:'flex', justifyContent:'flex-end', paddingTop:12}}><BuildBadge /></div>
        </Content>
      ) : (
        <Layout className="sp-layout">
          <Sider 
            className="sp-sidebar"
            width={250}
            breakpoint="lg"
            collapsible
            collapsed={collapsed}
            onCollapse={(val) => setCollapsed(val)}
            onBreakpoint={(broken) => setCollapsed(broken)}
            collapsedWidth={64}
            style={{
              background: 'var(--sp-bg-secondary)',
              backdropFilter: 'blur(10px)',
              borderRight: '1px solid var(--sp-border-primary)',
              height: 'calc(100vh - var(--sp-platform-header-height))',
              position: 'sticky',
              top: 'var(--sp-platform-header-height)',
              overflow: 'auto',
            }}
          >
            <div style={{ padding: 'var(--sp-spacing-md) 0' }}>
              <SectionBoundary label="PermissionBasedMenu"><PermissionBasedMenu inlineCollapsed={collapsed} /></SectionBoundary>
            </div>
          </Sider>

          <Content 
            className="sp-content"
            style={{ 
              padding: 'var(--sp-spacing-lg)',
              minHeight: 'calc(100vh - var(--sp-platform-header-height))',
              overflow: 'auto',
            }}
          >
            <SectionBoundary label="PageContent">{children}</SectionBoundary>
            <div style={{display:'flex', justifyContent:'flex-end', paddingTop:12}}><BuildBadge /></div>
          </Content>
        </Layout>
      )}
      <DiagPanel />
    </Layout>
  );
};

export default PlatformLayout;

// Локальная граница ошибок, чтобы не валить весь layout
class SectionBoundary extends React.Component<{ label: string; children: React.ReactNode }, { hasError: boolean; err?: any }>{
  constructor(props:any){ super(props); this.state = { hasError: false }; }
  static getDerivedStateFromError(error:any){ return { hasError: true, err: error }; }
  componentDidCatch(error:any, info:any){ try{ console.error('[SectionBoundary]', this.props.label, error, info); }catch{} }
  render(){
    if(this.state.hasError){
      return (
        <div style={{padding:6, border:'1px dashed #ef4444', borderRadius:6, color:'#ef4444', background:'rgba(239,68,68,0.06)'}}>
          {this.props.label} ошибка
        </div>
      );
    }
    return this.props.children as any;
  }
}
