// Унифицированные типы UI-конфигурации (P23/P22)

export type FeatureFlags = Record<string, boolean>;

export interface UIRole {
  id?: number;
  name: string;
  description?: string;
}

export type UIMenuGroup = 'core' | 'chat' | 'soul' | 'admin' | 'settings';

export interface UIMenuItem {
  key: string;
  label: string;
  icon?: string;
  path: string;
  group?: UIMenuGroup;
  featureKey?: string; // фичефлаг, управляющий видимостью
  requiredRoles?: string[]; // список ролей, которым доступен пункт
}

export interface UIConfig {
  user_id: number;
  roles: string[];
  menu_items: UIMenuItem[];
  features: FeatureFlags;
  ui_theme?: string;
}

export const defaultGroupLabels: Record<UIMenuGroup, string> = {
  core: 'Основное',
  chat: 'Чат',
  soul: 'Soul',
  admin: 'Администрирование',
  settings: 'Настройки',
};

export function inferGroupByPath(path: string): UIMenuGroup {
  if (path.startsWith('/chat') || path.startsWith('/telegram-chat') || path.startsWith('/chat-management')) return 'chat';
  if (path.startsWith('/soul/')) return 'soul';
  if (path === '/admin' || path.startsWith('/admin/') || path.startsWith('/rbac')) return 'admin';
  if (path === '/settings' || path === '/llm-settings' || path === '/payments' || path === '/help' || path === '/keywords') return 'settings';
  return 'core';
}


