import React, { useEffect, useMemo, useState } from 'react';
import { Menu, Spin, message } from 'antd';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  MessageOutlined,
  SettingOutlined,
  BulbOutlined,
  TagsOutlined,
  CalendarOutlined,
  ToolOutlined,
  CreditCardOutlined,
  HomeOutlined,
  QuestionCircleOutlined,
  SafetyOutlined,
} from '@ant-design/icons';
import { usePermissions, usePlatform } from '../hooks/usePermissions';
import { buildAuthHeaders } from '../api';
import type { UIConfig as UIConfigUnified, UIMenuItem, UIMenuGroup } from '../types/ui';
import { inferGroupByPath } from '../types/ui';

// Маппинг иконок
const iconMap = {
  MessageOutlined,
  SettingOutlined,
  BulbOutlined,
  TagsOutlined,
  CalendarOutlined,
  ToolOutlined,
  CreditCardOutlined,
  HomeOutlined,
  QuestionCircleOutlined,
  SafetyOutlined,
};

// Локальные интерфейсы заменены унифицированными типами из ../types/ui

interface PermissionBasedMenuProps {
  inlineCollapsed?: boolean;
  modeOverride?: 'horizontal' | 'inline';
}

const PermissionBasedMenu: React.FC<PermissionBasedMenuProps> = ({ inlineCollapsed = false, modeOverride }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { state: permissionsState } = usePermissions();
  const { platform, isMiniApp } = usePlatform();
  
  const [uiConfig, setUiConfig] = useState<UIConfigUnified | null>(null);
  const [loading, setLoading] = useState(true);
  const [fadeIn, setFadeIn] = useState(false);
  const abortRef = React.useRef<AbortController | null>(null);
  const seqRef = React.useRef<number>(0);

  // Загрузка конфигурации UI
  useEffect(() => {
    const fetchUIConfig = async () => {
      try {
        setLoading(true);
        // Быстрый показ из кэша
        try {
          const raw = sessionStorage.getItem('sp_ui_config');
          const atRaw = sessionStorage.getItem('sp_ui_config_at');
          const fresh = atRaw ? (Date.now() - Number(atRaw)) < 5*60*1000 : false;
          if (raw && fresh && !uiConfig) {
            setUiConfig(JSON.parse(raw));
          }
        } catch {}
        // Быстрый офлайн‑фолбек: если нет tg_id — не делаем сетевые вызовы
        // Пытаемся получить tg_id (WebApp → sessionStorage → JWT payload)
        const tgIdQuick = (() => {
          try {
            const wa = (typeof window !== 'undefined') ? (window as any).Telegram?.WebApp : undefined;
            const waId = wa?.initDataUnsafe?.user?.id?.toString();
            if (waId) return waId;
          } catch {}
          try { const sid = window.sessionStorage?.getItem('tg_id'); if (sid) return sid; } catch {}
          try {
            const tok = (typeof window !== 'undefined') ? (window.sessionStorage?.getItem('token') || window.localStorage?.getItem('token')) : null;
            if (tok) {
              const parts = tok.split('.');
              if (parts.length >= 2) {
                const pad = (s: string) => s + '='.repeat((4 - (s.length % 4)) % 4);
                const b64 = pad(parts[1].replace(/-/g, '+').replace(/_/g, '/'));
                const json = typeof atob === 'function' ? decodeURIComponent(Array.prototype.map.call(atob(b64), (c: string) => '%'+('00'+c.charCodeAt(0).toString(16)).slice(-2)).join('')) : '';
                if (json) {
                  const payload = JSON.parse(json);
                  const claim = String(payload.tg_id || payload.sub || '');
                  if (claim) {
                    try { window.sessionStorage?.setItem('tg_id', claim); } catch {}
                    return claim;
                  }
                }
              }
            }
          } catch {}
          return '';
        })();
        if (!tgIdQuick) {
          // Без tg_id — не подменяем меню локально, ждём корректной авторизации
          setUiConfig(null);
          try { console.log('[Menu] No tg_id. UI menu disabled until auth.'); } catch {}
          return;
        }

        // Отменяем предыдущие запросы для избежания гонок
        if (abortRef.current) { try { abortRef.current.abort(); } catch {} }
        abortRef.current = new AbortController();
        const mySeq = ++seqRef.current;
        // P23/P22: предпочитаем новый фасад /api/ui/config с фолбеком на /api/user/ui-config
        let response = await fetch('/api/ui/config', { headers: buildAuthHeaders(), signal: abortRef.current.signal });
        if (!response.ok) {
          response = await fetch('/api/user/ui-config', { headers: buildAuthHeaders(), signal: abortRef.current.signal });
        }
        if (response.status === 401) {
          // Без локальных заглушек — меню скрыто до авторизации
          setUiConfig(null);
          setLoading(false);
          return;
        }

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }

        const config: UIConfigUnified = await response.json();
        // Показываем строго серверный ответ без локальных добавлений
        const roles: string[] = Array.isArray(config.roles) ? config.roles : [];
        const items: UIMenuItem[] = Array.isArray(config.menu_items) ? config.menu_items : [];
        if (mySeq !== seqRef.current) return; // устаревший ответ
        const nextConfig = { ...config, roles, menu_items: items } as UIConfigUnified;
        const prevJson = uiConfig ? JSON.stringify(uiConfig) : '';
        const nextJson = JSON.stringify(nextConfig);
        if (prevJson !== nextJson) {
          setUiConfig(nextConfig);
          try {
            sessionStorage.setItem('sp_ui_config', nextJson);
            sessionStorage.setItem('sp_ui_config_at', String(Date.now()));
          } catch {}
        }
        try { console.log('[Menu] Loaded from API, items:', items.length, 'mode:', getMenuMode()); } catch {}
      } catch (error) {
        console.error('Ошибка загрузки конфигурации UI:', error);
        message.error('Не удалось загрузить конфигурацию меню');
        
        // Без локальных заглушек — меню скрыто до успешной загрузки с сервера
        if (!uiConfig) setUiConfig(null);
        try { console.log('[Menu] Error loading. UI menu disabled.'); } catch {}
      } finally {
        setLoading(false);
      }
    };

    // Загружаем конфигурацию только после загрузки полномочий
    if (!permissionsState.loading) {
      fetchUIConfig().then(() => { try { setTimeout(() => setFadeIn(true), 50); } catch {} });
    }
  }, [permissionsState.loading]);

  // Обработка клика по пункту меню
  const handleMenuClick = (item: { key: string }) => {
    if (item.key === 'all-pages') { navigate('/all-pages'); return; }
    const menuItem = uiConfig?.menu_items.find(mi => mi.key === item.key);
    if (menuItem) navigate(menuItem.path);
  };

  // Мемо: активный ключ и сгруппированные пункты
  const selectedKeys = useMemo(() => {
    if (!uiConfig) return [] as string[];
    const currentPath = location.pathname;
    const activeItem = uiConfig.menu_items.find(item => item.path === currentPath);
    return activeItem ? [activeItem.key] : [];
  }, [uiConfig, location.pathname]);

  const groupedItems = useMemo(() => {
    const groups: Record<UIMenuGroup, UIMenuItem[]> = { core: [], chat: [], soul: [], admin: [], settings: [] } as any;
    (uiConfig?.menu_items || []).forEach(mi => {
      const g = (mi.group || inferGroupByPath(mi.path)) as UIMenuGroup;
      groups[g] = groups[g] || [];
      groups[g].push(mi);
    });
    return groups;
  }, [uiConfig]);

  // Рендеринг иконки
  const renderIcon = (iconName: string) => {
    const IconComponent = iconMap[iconName as keyof typeof iconMap];
    return IconComponent ? <IconComponent /> : <QuestionCircleOutlined />;
  };

  // Адаптация меню для мини-апп
  const getMenuMode = () => {
    return modeOverride ? modeOverride : (isMiniApp ? 'horizontal' : 'inline');
  };

  // Рендер скелетонов для режима загрузки без мигания
  if (loading || permissionsState.loading) {
    const mode = getMenuMode();
    if (mode === 'horizontal') {
      return (
        <div style={{ display:'flex', gap:12, padding:'8px 12px' }}>
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} style={{ width: 80, height: 18, borderRadius: 9, background:'linear-gradient(90deg, rgba(200,200,200,0.25), rgba(160,160,160,0.35), rgba(200,200,200,0.25))', animation:'sp-skeleton 1.2s ease-in-out infinite', opacity:0.8 }} />
          ))}
        </div>
      );
    }
    return (
      <div style={{ padding: 12 }}>
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} style={{ display:'flex', alignItems:'center', gap:10, padding:'8px 6px' }}>
            <div style={{ width: 18, height: 18, borderRadius: 4, background:'linear-gradient(90deg, rgba(200,200,200,0.25), rgba(160,160,160,0.35), rgba(200,200,200,0.25))', animation:'sp-skeleton 1.2s ease-in-out infinite' }} />
            <div style={{ flex:'0 0 160px', height: 14, borderRadius: 7, background:'linear-gradient(90deg, rgba(200,200,200,0.25), rgba(160,160,160,0.35), rgba(200,200,200,0.25))', animation:'sp-skeleton 1.2s ease-in-out infinite' }} />
          </div>
        ))}
      </div>
    );
  }

  if (!uiConfig) {
    // Безопасный фолбек без API: показываем минимальные пункты (чат/домой)
    const fallbackItems: UIMenuItem[] = [
      { key: 'home', label: 'Главная', icon: 'HomeOutlined', path: '/' } as any,
      { key: 'chat', label: 'Чат', icon: 'MessageOutlined', path: '/chat' } as any,
      { key: 'reminders', label: 'Напоминания', icon: 'CalendarOutlined', path: '/reminders' } as any,
    ];
    if (getMenuMode() === 'horizontal') {
      return (
        <Menu mode="horizontal" onClick={handleMenuClick} style={{borderBottom:'none', backgroundColor:'transparent', transition:'opacity 180ms ease', opacity: fadeIn ? 1 : 0.001}}
          items={[...fallbackItems.map(it=>({key:it.key, icon:renderIcon(it.icon), label:it.label}))]} />
      );
    }
    return (
      <Menu mode="inline" onClick={handleMenuClick} style={{ transition:'opacity 180ms ease', opacity: fadeIn ? 1 : 0.001 }}
        items={[...fallbackItems.map(it=>({key:it.key, icon:renderIcon(it.icon), label:it.label}))]} />
    );
  }

  // Специальная обработка для мини-апп
  if (getMenuMode() === 'horizontal') {
    return (
      <Menu
        mode="horizontal"
        selectedKeys={selectedKeys}
        onClick={handleMenuClick}
        style={{
          borderBottom: 'none',
          backgroundColor: 'transparent',
          justifyContent: 'center',
          minWidth: 0,
          flexWrap: 'nowrap',
          overflowX: 'auto',
          transition:'opacity 180ms ease',
          opacity: fadeIn ? 1 : 0.001
        }}
        items={[
          ...(uiConfig.menu_items).map(item => ({
          key: item.key,
          icon: renderIcon(item.icon),
          label: item.label,
          })),
          { key: 'reminders', label: 'Напоминания', icon: renderIcon('CalendarOutlined') },
          { key: 'all-pages', label: 'Все страницы', icon: renderIcon('QuestionCircleOutlined') }
        ]}
      />
    );
  }

  // Обычное меню для веб-версии
  return (
    <Menu
      mode="inline"
      selectedKeys={selectedKeys}
      onClick={handleMenuClick}
      style={{ height: '100%', borderRight: 0, transition:'opacity 180ms ease', opacity: fadeIn ? 1 : 0.001 }}
      inlineCollapsed={inlineCollapsed}
      items={[
        ...(uiConfig.menu_items).map(item => ({
        key: item.key,
        icon: renderIcon(item.icon),
        label: item.label,
        })),
        { key: 'reminders', icon: renderIcon('CalendarOutlined'), label: 'Напоминания' },
        { key: 'all-pages', icon: renderIcon('QuestionCircleOutlined'), label: 'Все страницы' }
      ]}
    />
  );
};

export default PermissionBasedMenu;
