import React from 'react';

const BuildBadge: React.FC = () => {
  const buildId = (() => {
    try { return String((window as any).__SP_BUILD__ || ''); } catch { return ''; }
  })();
  if (!buildId) return null;
  return (
    <div style={{ fontSize: 11, color: 'var(--sp-text-secondary)', opacity: 0.8 }} title="Build ID">
      build: {buildId}
    </div>
  );
};

export default BuildBadge;


