/**
 * 🌙 ThemeToggle Component
 * Компонент для переключения тем
 */

import React from 'react';
import { Button, Dropdown, Space, Typography } from 'antd';
import { 
  SunOutlined, 
  MoonOutlined, 
  SettingOutlined,
  CheckOutlined 
} from '@ant-design/icons';
import { useTheme } from '../hooks/useTheme';
import type { ThemeName } from '../styles/themes';

const { Text } = Typography;

interface ThemeToggleProps {
  /** Размер кнопки */
  size?: 'small' | 'middle' | 'large';
  
  /** Тип отображения */
  variant?: 'icon' | 'button' | 'dropdown';
  
  /** Показывать текст */
  showText?: boolean;
  
  /** Дополнительные стили */
  style?: React.CSSProperties;
  
  /** CSS класс */
  className?: string;
}

const ThemeToggle: React.FC<ThemeToggleProps> = ({
  size = 'middle',
  variant = 'icon',
  showText = false,
  style,
  className,
}) => {
  const { 
    currentTheme, 
    resolvedTheme, 
    setTheme, 
    toggleTheme, 
    isDark, 
    isLight, 
    isAuto,
    availableThemes 
  } = useTheme();

  // Иконки для тем
  const getThemeIcon = (theme: ThemeName | 'resolved') => {
    switch (theme) {
      case 'light':
        return <SunOutlined />;
      case 'dark':
        return <MoonOutlined />;
      case 'auto':
        return <SettingOutlined />;
      case 'resolved':
        return resolvedTheme === 'dark' ? <MoonOutlined /> : <SunOutlined />;
      default:
        return <SettingOutlined />;
    }
  };

  // Названия тем
  const getThemeName = (theme: ThemeName) => {
    switch (theme) {
      case 'light':
        return 'Светлая';
      case 'dark':
        return 'Темная';
      case 'auto':
        return 'Авто';
      default:
        return 'Неизвестная';
    }
  };

  // Описания тем
  const getThemeDescription = (theme: ThemeName) => {
    switch (theme) {
      case 'light':
        return 'Светлая тема для дневного использования';
      case 'dark':
        return 'Темная тема для комфортного просмотра';
      case 'auto':
        return 'Автоматически следует системным настройкам';
      default:
        return '';
    }
  };

  // Простое переключение (только иконка)
  if (variant === 'icon') {
    return (
      <Button
        type="text"
        size={size}
        icon={getThemeIcon('resolved')}
        onClick={toggleTheme}
        style={{
          color: 'var(--sp-text-primary)',
          ...style,
        }}
        className={className}
        title={`Текущая тема: ${getThemeName(currentTheme)}${isAuto ? ` (${resolvedTheme})` : ''}`}
      />
    );
  }

  // Кнопка с текстом
  if (variant === 'button') {
    return (
      <Button
        type="default"
        size={size}
        icon={getThemeIcon('resolved')}
        onClick={toggleTheme}
        style={style}
        className={className}
      >
        {showText && (
          <span>
            {getThemeName(currentTheme)}
            {isAuto && ` (${resolvedTheme})`}
          </span>
        )}
      </Button>
    );
  }

  // Выпадающее меню с выбором темы
  if (variant === 'dropdown') {
    const menuItems = availableThemes.map((theme) => ({
      key: theme,
      label: (
        <Space>
          {getThemeIcon(theme)}
          <div>
            <div style={{ fontWeight: currentTheme === theme ? 600 : 400 }}>
              {getThemeName(theme)}
              {currentTheme === theme && (
                <CheckOutlined style={{ marginLeft: 8, color: 'var(--sp-color-success)' }} />
              )}
            </div>
            <Text type="secondary" style={{ fontSize: '12px' }}>
              {getThemeDescription(theme)}
            </Text>
          </div>
        </Space>
      ),
      onClick: () => setTheme(theme),
    }));

    return (
      <Dropdown
        menu={{ items: menuItems }}
        placement="bottomRight"
        trigger={['click']}
      >
        <Button
          type="text"
          size={size}
          style={{
            color: 'var(--sp-text-primary)',
            ...style,
          }}
          className={className}
        >
          <Space>
            {getThemeIcon('resolved')}
            {showText && (
              <span>
                {getThemeName(currentTheme)}
                {isAuto && ` (${resolvedTheme})`}
              </span>
            )}
          </Space>
        </Button>
      </Dropdown>
    );
  }

  return null;
};

// ===== ДОПОЛНИТЕЛЬНЫЕ КОМПОНЕНТЫ =====

/**
 * Компактный переключатель для мини-апп
 */
export const MiniAppThemeToggle: React.FC = () => (
  <ThemeToggle
    variant="icon"
    size="small"
    style={{
      position: 'fixed',
      top: '16px',
      right: '16px',
      zIndex: 1000,
      background: 'var(--sp-bg-card)',
      border: '1px solid var(--sp-border-primary)',
      borderRadius: '50%',
      width: '40px',
      height: '40px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      backdropFilter: 'blur(10px)',
      boxShadow: 'var(--sp-shadow-md)',
    }}
  />
);

/**
 * Переключатель для веб-версии с полным меню
 */
export const WebThemeToggle: React.FC = () => (
  <ThemeToggle
    variant="dropdown"
    size="middle"
    showText={true}
  />
);

/**
 * Простая кнопка переключения
 */
export const SimpleThemeToggle: React.FC = () => (
  <ThemeToggle
    variant="button"
    size="middle"
    showText={false}
  />
);

// ===== ХУКИ ДЛЯ УДОБСТВА =====

/**
 * Хук для получения стилей переключателя темы
 */
export const useThemeToggleStyles = () => {
  const { isDark, isLight } = useTheme();
  
  return {
    button: {
      background: isDark ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)',
      border: `1px solid ${isDark ? 'rgba(255, 255, 255, 0.2)' : 'rgba(0, 0, 0, 0.2)'}`,
      color: isDark ? '#ffffff' : '#000000',
      borderRadius: '8px',
      transition: 'all 0.2s ease',
      
      '&:hover': {
        background: isDark ? 'rgba(255, 255, 255, 0.2)' : 'rgba(0, 0, 0, 0.2)',
        transform: 'translateY(-1px)',
      },
    },
    
    dropdown: {
      background: 'var(--sp-bg-card)',
      border: '1px solid var(--sp-border-primary)',
      borderRadius: 'var(--sp-radius-lg)',
      boxShadow: 'var(--sp-shadow-lg)',
      backdropFilter: 'blur(10px)',
    },
  };
};

export default ThemeToggle;
