import React from 'react';
import { API_BASE } from '../api';

const getFlags = (): Record<string, unknown> => {
  try { return (window as any).__SP_FLAGS__ || {}; } catch { return {}; }
};

const getBuildId = (): string => {
  try { return String((window as any).__SP_BUILD__ || 'unknown'); } catch { return 'unknown'; }
};

const getRouterKind = (): string => {
  // По ТЗ используем MemoryRouter
  return 'MemoryRouter';
};

const getUa = (): string => {
  try { return navigator.userAgent; } catch { return ''; }
};

const isDiagEnabled = (): boolean => {
  try {
    const usp = new URLSearchParams(window.location.search);
    if (usp.get('diag') === '1') return true;
    const flags = getFlags();
    return (flags as any).DIAG === true;
  } catch { return false; }
};

const Section: React.FC<{ title: string } & React.HTMLAttributes<HTMLDivElement>> = ({ title, children, ...rest }) => (
  <div style={{ marginBottom: 8 }} {...rest}>
    <div style={{ fontSize: 12, color: '#9CA3AF', marginBottom: 4 }}>{title}</div>
    <div style={{ fontSize: 12, lineHeight: 1.5, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>{children}</div>
  </div>
);

const DiagPanel: React.FC = () => {
  if (!isDiagEnabled()) return null;

  const flags = getFlags();
  const buildId = getBuildId();
  const href = (() => { try { return window.location.href; } catch { return ''; } })();

  return (
    <div
      style={{
        position: 'fixed',
        right: 8,
        bottom: 8,
        zIndex: 2147483647,
        background: 'rgba(2,6,23,0.92)',
        color: '#E5E7EB',
        border: '1px solid rgba(51,65,85,0.7)',
        borderRadius: 8,
        padding: 10,
        maxWidth: 380,
        boxShadow: '0 6px 24px rgba(0,0,0,0.35)'
      }}
    >
      <div style={{ fontWeight: 700, marginBottom: 8 }}>DIAG</div>
      <Section title="Build">
        {buildId}
      </Section>
      <Section title="API_BASE">
        {API_BASE}
      </Section>
      <Section title="Router">
        {getRouterKind()}
      </Section>
      <Section title="Flags">
        {(() => {
          try { return JSON.stringify(flags, null, 2); } catch { return '{}'; }
        })()}
      </Section>
      <Section title="Location">
        {href}
      </Section>
      <Section title="User-Agent">
        {getUa()}
      </Section>
    </div>
  );
};

export default DiagPanel;


